// Cell Cycle and Cell Division — generated by Claude (no source PDF).
// Covers phases of the cell cycle (interphase: G1/S/G2, M phase), mitosis
// (prophase/metaphase/anaphase/telophase), cytokinesis, meiosis I & II,
// synapsis/crossing over, and the significance of mitosis vs meiosis.

export const CELL_CYCLE_DIVISION = [
  // ---- MCQ ----
  { id: 'ccd-1', type: 'mcq', question: 'The cell cycle is broadly divided into which two main phases?', options: ['G1 and G2 phase', 'Interphase and M phase (Mitotic phase)', 'Synthesis and Mitosis only', 'Prophase and Telophase'], correctIndex: 1, explanation: 'The cell cycle consists of interphase (preparatory phase) followed by the M phase (actual division).', difficulty: 'easy' },
  { id: 'ccd-2', type: 'mcq', question: 'Interphase is further divided into three sub-phases:', options: ['Prophase, Metaphase, Anaphase', 'G1, S, and G2 phases', 'G0, G1, and M phases', 'Synapsis, Crossing over, Terminalisation'], correctIndex: 1, explanation: 'Interphase comprises the G1 (Gap 1), S (Synthesis), and G2 (Gap 2) phases.', difficulty: 'easy' },
  { id: 'ccd-3', type: 'mcq', question: 'DNA replication occurs during which phase of the cell cycle?', options: ['G1 phase', 'S phase', 'G2 phase', 'M phase'], correctIndex: 1, explanation: 'The S (synthesis) phase is when DNA replication occurs, doubling the DNA content.', difficulty: 'easy' },
  { id: 'ccd-4', type: 'mcq', question: "A cell that has temporarily or permanently stopped dividing, exiting the active cell cycle, is said to be in which stage?", options: ['G1 phase', 'S phase', 'G0 phase (quiescent stage)', 'G2 phase'], correctIndex: 2, explanation: 'The G0 (quiescent) stage is a resting stage some cells enter, exiting the active cycle.', difficulty: 'medium' },
  { id: 'ccd-5', type: 'mcq', question: 'During the G1 phase, a cell is metabolically active and:', options: ['Undergoes DNA replication', 'Grows continuously and synthesises RNA/proteins needed for the S phase', 'Immediately divides into two daughter cells', 'Undergoes crossing over'], correctIndex: 1, explanation: 'G1 is a growth phase where the cell prepares (via RNA/protein synthesis) for DNA replication in S phase.', difficulty: 'medium' },
  { id: 'ccd-6', type: 'mcq', question: 'Proteins required for cell division are synthesised primarily during which phase?', options: ['G1 phase', 'S phase', 'G2 phase', 'Only during metaphase'], correctIndex: 2, explanation: 'G2 phase involves synthesis of proteins needed for the actual process of cell division (M phase).', difficulty: 'medium' },
  { id: 'ccd-7', type: 'mcq', question: 'Mitosis is also referred to as:', options: ['Reductional division', 'Equational division', 'Meiotic division', 'Synaptic division'], correctIndex: 1, explanation: 'Mitosis produces daughter cells genetically identical (equal) to the parent, hence "equational division".', difficulty: 'easy' },
  { id: 'ccd-8', type: 'mcq', question: 'Meiosis is also referred to as:', options: ['Equational division', 'Reductional division', 'Synthetic division', 'Amitotic division'], correctIndex: 1, explanation: 'Meiosis reduces the chromosome number by half, hence "reductional division".', difficulty: 'easy' },
  { id: 'ccd-9', type: 'mcq', question: 'The four sequential phases of mitosis (M phase) are:', options: ['G1, S, G2, M', 'Prophase, Metaphase, Anaphase, Telophase', 'Leptotene, Zygotene, Pachytene, Diplotene', 'Interphase, Prophase, Metaphase, Cytokinesis'], correctIndex: 1, explanation: 'Mitosis proceeds through prophase, metaphase, anaphase, and telophase.', difficulty: 'easy' },
  { id: 'ccd-10', type: 'mcq', question: 'During prophase of mitosis, chromosomal material condenses to form:', options: ['Chromatin threads only', 'Compact, visible mitotic chromosomes made of two chromatids', 'A nuclear membrane', 'A spindle apparatus only'], correctIndex: 1, explanation: 'Chromatin condenses into visible chromosomes, each consisting of two chromatids, during prophase.', difficulty: 'medium' },
  { id: 'ccd-11', type: 'mcq', question: 'The nuclear envelope and nucleolus disappear during which phase of mitosis?', options: ['Interphase', 'Prophase (towards the end)', 'Anaphase', 'Telophase'], correctIndex: 1, explanation: 'By the end of prophase, the Golgi complex, ER, nucleolus, and nuclear envelope disintegrate.', difficulty: 'medium' },
  { id: 'ccd-12', type: 'mcq', question: 'During metaphase, chromosomes align at which structure?', options: ['The nuclear membrane', 'The metaphase plate at the cell equator', 'The cell poles', 'The Golgi apparatus'], correctIndex: 1, explanation: 'Metaphase chromosomes align along the equatorial plate, attached to spindle fibres via kinetochores.', difficulty: 'easy' },
  { id: 'ccd-13', type: 'mcq', question: 'The structure on the chromosome to which spindle fibres attach is called the:', options: ['Centromere / kinetochore', 'Chromatid arm', 'Nucleolus', 'Nuclear pore'], correctIndex: 0, explanation: 'Spindle fibres attach to the kinetochore, a protein structure at the centromere.', difficulty: 'medium' },
  { id: 'ccd-14', type: 'mcq', question: 'During anaphase, what event occurs?', options: ['Chromosomes condense for the first time', 'Centromeres split and sister chromatids move to opposite poles', 'The nuclear envelope reforms', 'DNA replication begins'], correctIndex: 1, explanation: 'Anaphase is marked by centromere splitting and sister chromatids being pulled to opposite poles.', difficulty: 'easy' },
  { id: 'ccd-15', type: 'mcq', question: 'During telophase, which of the following occurs?', options: ['Chromosomes align at the equatorial plate', 'Chromosomes cluster at each pole, decondense, and the nuclear envelope reassembles', 'Centromeres split', 'DNA replicates'], correctIndex: 1, explanation: 'Telophase sees chromosome decondensation and nuclear envelope reformation around each set at the poles.', difficulty: 'easy' },
  { id: 'ccd-16', type: 'mcq', question: 'The division of the cytoplasm following mitotic nuclear division is called:', options: ['Karyokinesis', 'Cytokinesis', 'Synapsis', 'Interphase'], correctIndex: 1, explanation: 'Cytokinesis is the division of the cytoplasm, typically following karyokinesis (nuclear division).', difficulty: 'easy' },
  { id: 'ccd-17', type: 'mcq', question: 'In animal cells, cytokinesis occurs by:', options: ['Formation of a cell plate', 'Formation of a furrow that constricts the plasma membrane inward', 'Formation of a new cell wall from the outside', 'Direct division of the nucleus only'], correctIndex: 1, explanation: 'Animal cells divide via a cleavage furrow that pinches the cell into two.', difficulty: 'medium' },
  { id: 'ccd-18', type: 'mcq', question: 'In plant cells, cytokinesis occurs by:', options: ['Formation of a cleavage furrow', 'Formation of a cell plate that grows outward to form a new cell wall', 'Complete absence of any cytoplasmic division', 'Direct fragmentation of the parent cell'], correctIndex: 1, explanation: 'Plant cells, having rigid walls, divide via a cell plate that forms centrifugally and matures into a new cell wall.', difficulty: 'medium' },
  { id: 'ccd-19', type: 'mcq', question: 'Meiosis occurs in cells that are undergoing:', options: ['Normal somatic growth', 'Gametogenesis (formation of gametes)', 'Only wound healing', 'Only regeneration of lost body parts'], correctIndex: 1, explanation: 'Meiosis is restricted to reproductive cells during gamete formation, halving the chromosome number.', difficulty: 'easy' },
  { id: 'ccd-20', type: 'mcq', question: 'Meiosis involves how many sequential rounds of DNA replication and nuclear division?', options: ['One round of DNA replication followed by two rounds of nuclear division', 'Two rounds of DNA replication followed by one round of nuclear division', 'Two rounds of DNA replication and two rounds of division', 'No DNA replication at all'], correctIndex: 0, explanation: 'Meiosis has a single round of DNA replication followed by two successive nuclear divisions (Meiosis I and II).', difficulty: 'medium' },
  { id: 'ccd-21', type: 'mcq', question: 'Meiosis I is best described as a:', options: ['Equational division separating sister chromatids', 'Reductional division separating homologous chromosomes', 'Division that does not involve any chromosome movement', 'Process identical to mitosis in every way'], correctIndex: 1, explanation: 'Meiosis I separates homologous chromosomes, halving the chromosome number (reductional division).', difficulty: 'medium' },
  { id: 'ccd-22', type: 'mcq', question: 'Meiosis II is best described as being similar to:', options: ['Meiosis I', 'A mitotic division, separating sister chromatids', 'DNA replication only', 'Cytokinesis only'], correctIndex: 1, explanation: 'Meiosis II resembles mitosis, with sister chromatids separating to opposite poles.', difficulty: 'medium' },
  { id: 'ccd-23', type: 'mcq', question: 'Prophase I of meiosis is unique and more complex than mitotic prophase because it is subdivided into:', options: ['Two stages', 'Three stages', 'Five stages (Leptotene, Zygotene, Pachytene, Diplotene, Diakinesis)', 'No further subdivisions'], correctIndex: 2, explanation: 'Prophase I has five distinct sub-stages: leptotene, zygotene, pachytene, diplotene, and diakinesis.', difficulty: 'medium' },
  { id: 'ccd-24', type: 'mcq', question: 'During which sub-stage of prophase I does pairing (synapsis) of homologous chromosomes occur?', options: ['Leptotene', 'Zygotene', 'Pachytene', 'Diakinesis'], correctIndex: 1, explanation: 'Homologous chromosomes pair up (synapsis) during zygotene, forming bivalents.', difficulty: 'medium' },
  { id: 'ccd-25', type: 'mcq', question: 'The complex protein structure that forms between paired homologous chromosomes during synapsis is called the:', options: ['Kinetochore', 'Synaptonemal complex', 'Spindle apparatus', 'Nucleolar organiser'], correctIndex: 1, explanation: 'The synaptonemal complex is the structure formed between synapsed homologous chromosomes.', difficulty: 'medium' },
  { id: 'ccd-26', type: 'mcq', question: 'Crossing over — the exchange of genetic material between non-sister chromatids of homologous chromosomes — occurs during which sub-stage of prophase I?', options: ['Leptotene', 'Zygotene', 'Pachytene', 'Diplotene'], correctIndex: 2, explanation: 'Crossing over between non-sister chromatids of homologous chromosomes takes place during pachytene.', difficulty: 'medium' },
  { id: 'ccd-27', type: 'mcq', question: 'The X-shaped structures visible at the sites of crossing over during diplotene are called:', options: ['Centromeres', 'Chiasmata', 'Kinetochores', 'Nucleoli'], correctIndex: 1, explanation: 'Chiasmata are the visible sites where crossing over has occurred between homologous chromatids.', difficulty: 'medium' },
  { id: 'ccd-28', type: 'mcq', question: 'The process of terminalisation, in which chiasmata move towards the ends of the chromosomes, occurs during:', options: ['Leptotene', 'Zygotene', 'Diakinesis', 'Telophase II'], correctIndex: 2, explanation: 'Terminalisation of chiasmata is a hallmark of diakinesis, the final sub-stage of prophase I.', difficulty: 'medium' },
  { id: 'ccd-29', type: 'mcq', question: 'At the end of Meiosis I, the resulting two daughter cells are:', options: ['Diploid and genetically identical to the parent', 'Haploid, each with chromosomes still consisting of two chromatids', 'Diploid but genetically different from the parent', 'Already fully differentiated gametes'], correctIndex: 1, explanation: 'After Meiosis I, cells are haploid, though each chromosome still has two sister chromatids until Meiosis II.', difficulty: 'medium' },
  { id: 'ccd-30', type: 'mcq', question: 'The overall outcome of meiosis, starting from one diploid parent cell, is typically:', options: ['Two diploid daughter cells', 'Four haploid daughter cells', 'One tetraploid daughter cell', 'Two haploid and two diploid cells'], correctIndex: 1, explanation: 'A diploid parent cell undergoing meiosis ultimately produces four haploid daughter cells.', difficulty: 'easy' },
  { id: 'ccd-31', type: 'mcq', question: 'The primary biological significance of mitosis is to:', options: ['Introduce genetic variation through crossing over', 'Enable growth, repair, and asexual reproduction by producing genetically identical daughter cells', 'Halve the chromosome number for gamete formation', 'Combine chromosomes from two different cells'], correctIndex: 1, explanation: 'Mitosis maintains chromosome number and produces identical cells for growth, tissue repair, and asexual reproduction.', difficulty: 'easy' },
  { id: 'ccd-32', type: 'mcq', question: 'The primary biological significance of meiosis is to:', options: ['Repair damaged tissue', 'Maintain the constant chromosome number across generations in sexually reproducing organisms and generate genetic variation', 'Simply double the amount of DNA', 'Occur only in unicellular organisms'], correctIndex: 1, explanation: 'Meiosis halves the chromosome number (restoring it at fertilisation) and introduces variation through crossing over and independent assortment.', difficulty: 'medium' },
  { id: 'ccd-33', type: 'mcq', question: 'Cell cycle checkpoints, such as the G1/S checkpoint, primarily function to:', options: ['Speed up the cell cycle unconditionally', 'Ensure that conditions are suitable and DNA is undamaged before allowing progression to the next phase', 'Prevent DNA replication from ever occurring', 'Only function during meiosis'], correctIndex: 1, explanation: 'Checkpoints monitor cell conditions (like DNA integrity) before allowing the cycle to proceed, maintaining genomic stability.', difficulty: 'medium' },
  { id: 'ccd-34', type: 'mcq', question: 'Which of the following cells in the human body are typically found in the G0 (quiescent) phase under normal conditions?', options: ['Actively dividing bone marrow stem cells', 'Mature, differentiated neurons (which generally do not divide)', 'Cells of a rapidly growing tumour', 'Cells actively undergoing S phase'], correctIndex: 1, explanation: 'Highly differentiated cells like neurons typically remain non-dividing (in G0) for most/all of their functional life.', difficulty: 'medium' },
  { id: 'ccd-35', type: 'mcq', question: 'In a typical human somatic cell cycle, which phase generally occupies the largest proportion of the total cycle time?', options: ['M phase', 'Interphase', 'Cytokinesis alone', 'Anaphase alone'], correctIndex: 1, explanation: 'Interphase (G1+S+G2) typically occupies the vast majority (often over 95%) of the total cell cycle duration.', difficulty: 'medium' },
  { id: 'ccd-36', type: 'mcq', question: 'The number of chromatids present in a chromosome just before it enters mitotic prophase (having already replicated in S phase) is:', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'After S phase replication, each chromosome consists of two sister chromatids joined at the centromere.', difficulty: 'medium' },
  { id: 'ccd-37', type: 'mcq', question: "A cell with chromosome number 2n=8 that undergoes mitosis will produce daughter cells with a chromosome number of:", options: ['2n=4', '2n=8', '2n=16', 'n=4'], correctIndex: 1, explanation: 'Mitosis maintains the parental chromosome number, so daughter cells remain 2n=8.', difficulty: 'medium' },
  { id: 'ccd-38', type: 'mcq', question: "A cell with chromosome number 2n=8 that undergoes meiosis will produce daughter cells (gametes) with a chromosome number of:", options: ['2n=8', 'n=4', '2n=16', 'n=8'], correctIndex: 1, explanation: 'Meiosis halves the chromosome number, so gametes would have n=4.', difficulty: 'medium' },
  { id: 'ccd-39', type: 'mcq', question: 'The formation of bivalents (pairs of homologous chromosomes) during meiosis is a feature that is:', options: ['Also seen during mitosis', 'Unique to meiosis I and absent in mitosis', 'Seen in both meiosis I and meiosis II equally', 'Seen only in meiosis II'], correctIndex: 1, explanation: 'Bivalent formation via synapsis of homologous chromosomes is a hallmark unique to meiosis I, not seen in mitosis.', difficulty: 'medium' },
  { id: 'ccd-40', type: 'mcq', question: 'Independent assortment of homologous chromosome pairs, contributing to genetic variation, occurs during which phase?', options: ['Anaphase I of meiosis', 'Anaphase of mitosis', 'Telophase II of meiosis', 'S phase'], correctIndex: 0, explanation: 'During anaphase I, homologous pairs separate independently of one another, contributing to genetic variation among gametes.', difficulty: 'medium' },
  { id: 'ccd-41', type: 'mcq', question: 'The spindle apparatus, essential for chromosome movement during division, is primarily made up of:', options: ['Cellulose fibres', 'Microtubules', 'Peptidoglycan strands', 'Collagen fibres'], correctIndex: 1, explanation: 'The mitotic/meiotic spindle is composed of microtubules that attach to and move chromosomes.', difficulty: 'medium' },
  { id: 'ccd-42', type: 'mcq', question: 'In plant cells (which typically lack centrioles), spindle fibre organisation is instead managed by:', options: ['A polar cap made from cytoplasmic microtubular proteins', 'Mitochondria', 'The Golgi apparatus', 'Ribosomes'], correctIndex: 0, explanation: 'Plant cells organise spindle fibres from diffuse microtubule organising material at the poles, without centrioles.', difficulty: 'hard' },
  { id: 'ccd-43', type: 'mcq', question: 'Amitosis, a form of direct nuclear division without the formal stages of mitosis, was historically described in:', options: ['All plant cells', 'Certain cells like bacterial fission or some protist divisions', 'Only in human neurons', 'Only during meiosis II'], correctIndex: 1, explanation: 'Amitosis refers to simpler, direct forms of nuclear division seen in some prokaryotes/protists, without formal mitotic stages.', difficulty: 'hard' },
  { id: 'ccd-44', type: 'mcq', question: 'Which of the following would most directly result from a failure of the spindle checkpoint (allowing division to proceed with improperly attached chromosomes)?', options: ['Perfectly equal chromosome distribution every time', 'Aneuploidy — daughter cells with an abnormal number of chromosomes', 'Immediate cell death with no further consequences', 'No effect on the resulting daughter cells'], correctIndex: 1, explanation: 'Failure of the spindle checkpoint can allow improper chromosome segregation, resulting in aneuploid daughter cells.', difficulty: 'hard' },
  { id: 'ccd-45', type: 'mcq', question: 'Which of the following best distinguishes mitosis from meiosis in terms of the number of divisions per cycle?', options: ['Mitosis has two divisions per cycle; meiosis has one', 'Mitosis has one division per cycle; meiosis has two', 'Both have exactly two divisions per cycle', 'Neither involves more than one round of DNA replication or division'], correctIndex: 1, explanation: 'Mitosis is a single division producing two daughter cells; meiosis is two successive divisions producing four.', difficulty: 'easy' },
  { id: 'ccd-46', type: 'mcq', question: 'Which statement about genetic identity of daughter cells is correct?', options: ['Mitotic daughter cells are genetically identical to the parent cell; meiotic daughter cells show genetic variation', 'Meiotic daughter cells are always genetically identical to the parent; mitotic daughter cells vary', 'Both processes always produce genetically identical daughter cells', 'Neither process produces genetically similar daughter cells'], correctIndex: 0, explanation: 'Mitosis preserves genetic identity; meiosis introduces variation via crossing over and independent assortment.', difficulty: 'medium' },
  { id: 'ccd-47', type: 'mcq', question: 'Which of the following cell types in humans would normally be expected to undergo meiosis?', options: ['Skin epithelial cells', 'Primary spermatocytes/oocytes in the gonads', 'Liver cells during regeneration', 'Red blood cell precursors'], correctIndex: 1, explanation: 'Meiosis is specific to germ-line cells (like primary spermatocytes and oocytes) during gamete formation.', difficulty: 'medium' },
  { id: 'ccd-48', type: 'mcq', question: 'Which of the following correctly orders events from earliest to latest in mitosis?', options: ['Telophase → Anaphase → Metaphase → Prophase', 'Prophase → Metaphase → Anaphase → Telophase', 'Metaphase → Prophase → Telophase → Anaphase', 'Anaphase → Telophase → Prophase → Metaphase'], correctIndex: 1, explanation: 'The correct sequence of mitotic phases is Prophase → Metaphase → Anaphase → Telophase.', difficulty: 'easy' },
  { id: 'ccd-49', type: 'mcq', question: 'The term "karyokinesis" specifically refers to:', options: ['Division of the cytoplasm', 'Division of the nucleus', 'Formation of the cell wall', 'Formation of the spindle apparatus only'], correctIndex: 1, explanation: 'Karyokinesis is nuclear division, typically followed by cytokinesis (cytoplasmic division).', difficulty: 'easy' },
  { id: 'ccd-50', type: 'mcq', question: 'Which of these is the correct sequence of sub-stages within Prophase I of meiosis?', options: ['Pachytene → Leptotene → Zygotene → Diplotene → Diakinesis', 'Leptotene → Zygotene → Pachytene → Diplotene → Diakinesis', 'Diakinesis → Diplotene → Pachytene → Zygotene → Leptotene', 'Zygotene → Leptotene → Diakinesis → Pachytene → Diplotene'], correctIndex: 1, explanation: 'The correct order of Prophase I sub-stages is Leptotene → Zygotene → Pachytene → Diplotene → Diakinesis.', difficulty: 'medium' },

  // ---- Assertion-Reason ----
  { id: 'ccd-ar-1', type: 'assertion-reason', question: 'Assertion (A): Interphase is often called the "resting phase" of the cell cycle.\nReason (R): During interphase, the cell is metabolically inactive and shows no growth or preparation for division.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 2, explanation: "Interphase is popularly (though somewhat misleadingly) called the 'resting phase' (A is true), but the cell is actually highly metabolically active during interphase, preparing for division (R is false).", difficulty: 'medium' },
  { id: 'ccd-ar-2', type: 'assertion-reason', question: 'Assertion (A): DNA content doubles during the S phase of interphase.\nReason (R): DNA replication occurs specifically during the S (synthesis) phase.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'DNA replication during S phase is exactly what causes the DNA content to double.', difficulty: 'easy' },
  { id: 'ccd-ar-3', type: 'assertion-reason', question: 'Assertion (A): Some cells, like neurons, remain in the G0 phase for extended periods or permanently.\nReason (R): The G0 phase is an actively dividing stage where cells rapidly progress toward mitosis.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 2, explanation: 'A is true (neurons often stay in G0 long-term), but R is false — G0 is actually a quiescent, non-dividing stage, not an actively dividing one.', difficulty: 'medium' },
  { id: 'ccd-ar-4', type: 'assertion-reason', question: 'Assertion (A): Chromosomes become visible as distinct structures during prophase.\nReason (R): Chromatin material condenses and coils during prophase.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: "Condensation/coiling of chromatin into a compact form is exactly why chromosomes become visible during prophase.", difficulty: 'easy' },
  { id: 'ccd-ar-5', type: 'assertion-reason', question: 'Assertion (A): During metaphase, chromosomes align randomly throughout the cytoplasm.\nReason (R): Metaphase chromosomes align specifically at the equatorial (metaphase) plate.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Alignment is NOT random (A is false) — chromosomes specifically align at the metaphase plate, as R correctly states.', difficulty: 'medium' },
  { id: 'ccd-ar-6', type: 'assertion-reason', question: 'Assertion (A): Anaphase is characterised by the splitting of centromeres and movement of sister chromatids to opposite poles.\nReason (R): Spindle fibres attached to kinetochores shorten, pulling the separated chromatids apart.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Spindle fibre shortening after centromere splitting is exactly the mechanism driving chromatid separation in anaphase.', difficulty: 'medium' },
  { id: 'ccd-ar-7', type: 'assertion-reason', question: 'Assertion (A): Cytokinesis in plant cells occurs via a cleavage furrow, just as in animal cells.\nReason (R): The rigid cell wall of plant cells requires a different mechanism — a cell plate — for cytoplasmic division.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Plant cell cytokinesis actually occurs via a cell plate, not a cleavage furrow (A is false); R correctly explains why plants need this different mechanism.', difficulty: 'medium' },
  { id: 'ccd-ar-8', type: 'assertion-reason', question: 'Assertion (A): Meiosis I is a reductional division.\nReason (R): Homologous chromosomes separate during meiosis I, halving the chromosome number.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Separation of homologous chromosomes, halving the number, is exactly why meiosis I is termed reductional.', difficulty: 'medium' },
  { id: 'ccd-ar-9', type: 'assertion-reason', question: 'Assertion (A): Meiosis II is essentially similar to a mitotic division.\nReason (R): In meiosis II, sister chromatids separate, just as they do in mitotic anaphase.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'The shared mechanism of sister chromatid separation is exactly why meiosis II resembles mitosis.', difficulty: 'medium' },
  { id: 'ccd-ar-10', type: 'assertion-reason', question: 'Assertion (A): Prophase I of meiosis is much shorter and simpler than mitotic prophase.\nReason (R): Prophase I includes five distinct sub-stages, including pairing and crossing over of homologous chromosomes.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Prophase I is actually much longer and MORE complex than mitotic prophase (A is false), precisely because of its five distinct sub-stages including synapsis and crossing over (R is true).', difficulty: 'medium' },
  { id: 'ccd-ar-11', type: 'assertion-reason', question: 'Assertion (A): Synapsis refers to the pairing of homologous chromosomes.\nReason (R): This pairing occurs specifically during the zygotene sub-stage of prophase I.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Zygotene is defined as exactly the sub-stage in which this homologous pairing (synapsis) occurs.', difficulty: 'medium' },
  { id: 'ccd-ar-12', type: 'assertion-reason', question: 'Assertion (A): Crossing over increases genetic variation among gametes.\nReason (R): Crossing over involves the exchange of genetic segments between non-sister chromatids of homologous chromosomes.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Exchanging genetic segments between homologous chromatids directly creates new allele combinations, increasing variation.', difficulty: 'medium' },
  { id: 'ccd-ar-13', type: 'assertion-reason', question: 'Assertion (A): Chiasmata are visible structures representing sites of crossing over.\nReason (R): Chiasmata become visible during the diplotene sub-stage as homologous chromosomes begin to separate but remain connected at these points.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'The connection points remaining visible as homologs separate at diplotene is exactly what defines a chiasma.', difficulty: 'medium' },
  { id: 'ccd-ar-14', type: 'assertion-reason', question: 'Assertion (A): Meiosis produces four genetically identical haploid cells from one diploid parent cell.\nReason (R): Crossing over and independent assortment during meiosis ensure that the four resulting cells are generally genetically different from one another.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'The four cells are actually genetically DIFFERENT, not identical (A is false), precisely because of crossing over and independent assortment (R is true).', difficulty: 'medium' },
  { id: 'ccd-ar-15', type: 'assertion-reason', question: 'Assertion (A): Mitosis is essential for growth and tissue repair in multicellular organisms.\nReason (R): Mitosis produces genetically identical daughter cells that can replace damaged or lost cells.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Producing identical replacement cells is exactly why mitosis underlies growth and tissue repair.', difficulty: 'easy' },
  { id: 'ccd-ar-16', type: 'assertion-reason', question: 'Assertion (A): If meiosis did not occur in sexually reproducing organisms, the chromosome number would double every generation.\nReason (R): Fertilisation combines gametes from two parents, and without a prior reduction division, chromosome number would keep increasing.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: "Fertilisation combining full (unreduced) chromosome sets each generation is exactly why meiosis's halving step is essential to keep chromosome number constant.", difficulty: 'medium' },
  { id: 'ccd-ar-17', type: 'assertion-reason', question: 'Assertion (A): The spindle apparatus is composed mainly of actin filaments.\nReason (R): Microtubules, not actin filaments, are responsible for chromosome movement toward the poles during anaphase.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'The spindle apparatus is actually made of microtubules, not actin filaments (A is false); R correctly identifies microtubules as the real driver of chromosome movement.', difficulty: 'medium' },
  { id: 'ccd-ar-18', type: 'assertion-reason', question: "Assertion (A): Plant cells typically lack centrioles.\nReason (R): Despite lacking centrioles, plant cells can still form a functional spindle apparatus during division.", options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 1, explanation: 'Both statements are true, but R does not explain WHY plant cells lack centrioles — it simply notes that spindle formation still occurs despite this absence.', difficulty: 'hard' },
  { id: 'ccd-ar-19', type: 'assertion-reason', question: 'Assertion (A): Cell cycle checkpoints have no real biological importance and can be safely ignored by the cell.\nReason (R): Checkpoints help prevent cells with damaged DNA or improperly segregated chromosomes from continuing to divide.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Checkpoints are actually critically important, not ignorable (A is false); R correctly explains their real protective role.', difficulty: 'medium' },
  { id: 'ccd-ar-20', type: 'assertion-reason', question: 'Assertion (A): A cell with 2n=8 chromosomes will produce gametes with n=4 chromosomes via meiosis.\nReason (R): Meiosis involves one round of DNA replication followed by two rounds of nuclear division, halving the chromosome number overall.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: "This exact replication-then-double-division pattern is why the chromosome number ends up halved from 2n to n.", difficulty: 'medium' },

  // ---- Statement-based ----
  { id: 'ccd-st-1', type: 'statement', question: 'Statement I: Interphase consists of G1, S, and G2 phases.\nStatement II: DNA replication occurs during the G2 phase.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — DNA replication occurs in the S phase, not G2.', difficulty: 'easy' },
  { id: 'ccd-st-2', type: 'statement', question: 'Statement I: Cells in the G0 phase have permanently lost the ability to ever divide again under any circumstances.\nStatement II: Some G0 cells can re-enter the cell cycle if appropriately stimulated.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I overstates the case — some G0 cells CAN re-enter the cycle (Statement II correct), so I is incorrect.', difficulty: 'medium' },
  { id: 'ccd-st-3', type: 'statement', question: 'Statement I: Chromosomes are least condensed during metaphase.\nStatement II: Chromosomes are most condensed and clearly visible during metaphase.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — chromosomes are actually MOST (not least) condensed at metaphase, as Statement II correctly states.', difficulty: 'medium' },
  { id: 'ccd-st-4', type: 'statement', question: 'Statement I: Anaphase involves the splitting of centromeres.\nStatement II: Anaphase involves the movement of separated chromatids toward opposite poles.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe key events of anaphase.', difficulty: 'easy' },
  { id: 'ccd-st-5', type: 'statement', question: 'Statement I: Cytokinesis in animal cells involves formation of a cell plate.\nStatement II: Cytokinesis in plant cells involves formation of a cleavage furrow.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 1, explanation: 'Both statements have the mechanisms swapped — animal cells use a cleavage furrow, and plant cells use a cell plate.', difficulty: 'medium' },
  { id: 'ccd-st-6', type: 'statement', question: 'Statement I: Meiosis I separates homologous chromosomes.\nStatement II: Meiosis II separates sister chromatids.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly summarise the key distinguishing events of meiosis I and II.', difficulty: 'easy' },
  { id: 'ccd-st-7', type: 'statement', question: 'Statement I: Synapsis of homologous chromosomes occurs during pachytene.\nStatement II: Crossing over occurs during pachytene.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — synapsis occurs during zygotene, not pachytene; Statement II correctly places crossing over at pachytene.', difficulty: 'medium' },
  { id: 'ccd-st-8', type: 'statement', question: 'Statement I: Chiasmata are the visible manifestations of crossing over.\nStatement II: Chiasmata terminalisation occurs during diakinesis.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe chiasmata and their terminalisation in diakinesis.', difficulty: 'medium' },
  { id: 'ccd-st-9', type: 'statement', question: 'Statement I: Mitosis produces four haploid daughter cells from one diploid parent cell.\nStatement II: Meiosis produces four haploid daughter cells from one diploid parent cell.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — mitosis produces TWO diploid daughter cells, not four haploid ones; Statement II correctly describes the outcome of meiosis.', difficulty: 'medium' },
  { id: 'ccd-st-10', type: 'statement', question: 'Statement I: Mitosis introduces significant genetic variation in daughter cells.\nStatement II: Meiosis introduces genetic variation through crossing over and independent assortment.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — mitosis produces genetically IDENTICAL cells, introducing essentially no variation; Statement II correctly describes meiotic variation sources.', difficulty: 'medium' },
  { id: 'ccd-st-11', type: 'statement', question: 'Statement I: The kinetochore is the site where spindle fibres attach to a chromosome.\nStatement II: The kinetochore is located at the centromere.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the location and function of the kinetochore.', difficulty: 'easy' },
  { id: 'ccd-st-12', type: 'statement', question: 'Statement I: G1 phase involves cell growth and synthesis of RNA/proteins.\nStatement II: G2 phase involves synthesis of proteins required for cell division.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the general activities of G1 and G2 phases.', difficulty: 'medium' },
  { id: 'ccd-st-13', type: 'statement', question: 'Statement I: A cell in the S phase already has fully condensed, visible chromosomes.\nStatement II: Chromosome condensation into visible structures is a hallmark of prophase, not S phase.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — chromosomes remain as extended chromatin during S phase, not visibly condensed; Statement II correctly identifies prophase as the condensation stage.', difficulty: 'medium' },
  { id: 'ccd-st-14', type: 'statement', question: 'Statement I: Bivalent formation is a feature unique to meiosis, not seen in mitosis.\nStatement II: A bivalent consists of a pair of homologous chromosomes, each with two chromatids (a tetrad of four chromatids).', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe bivalent/tetrad formation as a meiosis-specific feature.', difficulty: 'medium' },
  { id: 'ccd-st-15', type: 'statement', question: 'Statement I: Amitosis is the standard, most common form of cell division in humans.\nStatement II: Mitosis is the standard form of somatic cell division in humans.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — amitosis is not the standard human division process; Statement II correctly identifies mitosis as standard.', difficulty: 'medium' },
  { id: 'ccd-st-16', type: 'statement', question: 'Statement I: Telophase is marked by decondensation of chromosomes.\nStatement II: The nuclear envelope reforms around each set of chromosomes during telophase.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe key telophase events.', difficulty: 'easy' },
  { id: 'ccd-st-17', type: 'statement', question: 'Statement I: A cell cycle checkpoint can halt the cycle if DNA damage is detected.\nStatement II: Checkpoints exist only during meiosis and not during mitosis.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — checkpoints operate during the mitotic cell cycle as well, not exclusively during meiosis.', difficulty: 'medium' },
  { id: 'ccd-st-18', type: 'statement', question: 'Statement I: Independent assortment occurs during anaphase I of meiosis.\nStatement II: Independent assortment contributes to genetic variation among gametes.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly connect independent assortment\'s timing and its role in generating variation.', difficulty: 'medium' },
  { id: 'ccd-st-19', type: 'statement', question: 'Statement I: A diploid cell with 2n=46 chromosomes (as in humans) will produce gametes with n=46 chromosomes via meiosis.\nStatement II: Human gametes normally contain n=23 chromosomes.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — meiosis halves the number, so gametes would have n=23, not n=46; Statement II correctly states the actual human gamete chromosome number.', difficulty: 'medium' },
  { id: 'ccd-st-20', type: 'statement', question: 'Statement I: Mitosis occurs in both somatic cells and germ-line cells during gamete formation.\nStatement II: Meiosis is restricted specifically to germ-line cells during gamete formation.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — gamete formation specifically involves MEIOSIS, not mitosis, in germ-line cells; Statement II correctly restricts meiosis to that context.', difficulty: 'medium' },

  // ---- "How many of the following are correct" ----
  { id: 'ccd-hm-1', type: 'statement', question: 'How many of the following are sub-phases of interphase?\nG1 phase, S phase, G2 phase, M phase', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'G1, S, and G2 are the three sub-phases of interphase; M phase is a separate, distinct main phase of the cell cycle.', difficulty: 'easy' },
  { id: 'ccd-hm-2', type: 'statement', question: 'How many of the following are correctly ordered stages of mitosis, in sequence?\nProphase, Metaphase, Anaphase, Telophase', options: ['One', 'Two', 'Three', 'All four, in this exact order'], correctIndex: 3, explanation: 'This is indeed the correct sequential order of all four mitotic stages.', difficulty: 'easy' },
  { id: 'ccd-hm-3', type: 'statement', question: 'How many of the following are sub-stages of Prophase I in meiosis?\nLeptotene, Zygotene, Pachytene, Metaphase', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Leptotene, zygotene, and pachytene are Prophase I sub-stages; metaphase is a separate, later main stage of meiosis I.', difficulty: 'medium' },
  { id: 'ccd-hm-4', type: 'statement', question: 'How many of the following events are correctly associated with meiosis but NOT with mitosis?\nSynapsis of homologous chromosomes, Crossing over, Formation of bivalents/tetrads, Splitting of sister chromatids', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Synapsis, crossing over, and bivalent formation are meiosis-specific; sister chromatid splitting occurs in BOTH mitosis and meiosis II.', difficulty: 'medium' },
  { id: 'ccd-hm-5', type: 'statement', question: 'How many of the following are true regarding cytokinesis?\nIt divides the cytoplasm following karyokinesis, Animal cells use a cleavage furrow, Plant cells use a cell plate, It occurs before karyokinesis in all organisms', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements are correct; cytokinesis typically follows (not precedes) karyokinesis, making the fourth statement false.', difficulty: 'medium' },
  { id: 'ccd-hm-6', type: 'statement', question: 'How many of the following correctly result from meiosis, starting with one diploid parent cell?\nFour haploid daughter cells, Genetic variation among the resulting cells, Two rounds of nuclear division, Only one round of DNA replication', options: ['One', 'Two', 'Three', 'All four'], correctIndex: 3, explanation: 'All four statements accurately describe the outcomes and process of meiosis.', difficulty: 'medium' },
  { id: 'ccd-hm-7', type: 'statement', question: 'How many of the following are functions/roles of cell cycle checkpoints?\nVerifying DNA is undamaged before replication, Ensuring chromosomes are properly attached to spindle fibres before anaphase, Preventing cell division altogether in all cells, Helping maintain genomic stability', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first, second, and fourth statements correctly describe checkpoint roles; checkpoints do NOT prevent division altogether — they only pause it when problems are detected.', difficulty: 'medium' },
  { id: 'ccd-hm-8', type: 'statement', question: "How many of the following would correctly describe a cell in the G0 phase?\nIt is metabolically inactive and dead, It has exited the active cell cycle, It may re-enter the cycle upon stimulation in some cell types, It always divides again within 24 hours", options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'The second and third statements correctly describe G0; the cell is NOT dead (still metabolically active in its function) and does not necessarily divide again within any fixed timeframe.', difficulty: 'medium' },
  { id: 'ccd-hm-9', type: 'statement', question: 'How many of the following are visible/occur specifically during diplotene and diakinesis (the later sub-stages of Prophase I)?\nChiasmata become visible, Terminalisation of chiasmata occurs, Synapsis of homologous chromosomes first begins, Homologous chromosomes start to separate while remaining connected at chiasmata', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Chiasmata visibility, terminalisation, and partial separation while connected are all diplotene/diakinesis features; synapsis actually FIRST begins earlier, during zygotene.', difficulty: 'hard' },
  { id: 'ccd-hm-10', type: 'statement', question: 'How many of the following statements about chromosome number are correct?\nMitosis maintains the parental chromosome number in daughter cells, Meiosis halves the chromosome number in daughter cells, Fertilisation restores the diploid chromosome number, A human gamete normally has 46 chromosomes', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'The first three statements are correct; a human gamete normally has 23 chromosomes (n), not 46 — that figure is for diploid somatic cells.', difficulty: 'medium' },
];
